var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();return scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true)).Select(r=>new{name=r.name,enabled=r.enabled,materials=r.sharedMaterials.Where(m=>m!=null).Select(m=>new{name=m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),shader=m.shader.name,color=m.HasProperty("_Color")?m.GetColor("_Color").ToString():null,baseColor=m.HasProperty("_BaseColor")?m.GetColor("_BaseColor").ToString():null,shade=m.HasProperty("_ShadeColor")?m.GetColor("_ShadeColor").ToString():null,gi=m.HasProperty("_GiEqualization")?m.GetFloat("_GiEqualization"):-1,light=m.HasProperty("_LightColorAttenuation")?m.GetFloat("_LightColorAttenuation"):-1}).ToArray()}).ToArray();
